/**
 * Procedural chiptune, composed on the fly from a seed: a chord progression
 * in a major key, a lead melody built from short motifs, a sixteenth-note
 * arpeggio, a triangle bass line and noise drums. Nothing is sampled or
 * transcribed; every song is generated by these rules.
 */

export type Drum = 'kick' | 'snare' | 'hat'
export type NoteEvent = { midi: number; steps: number }
export type StepEvents = { lead?: NoteEvent; arp?: NoteEvent; bass?: NoteEvent; drum?: Drum }

export type Song = {
  seed: number
  /** MIDI note of the key's tonic (lead register). */
  root: number
  /** Chord per bar as a scale degree (0 = I … 6 = vii). */
  chords: number[]
  steps: StepEvents[]
}

export const STEPS_PER_BAR = 16
export const BARS_PER_SONG = 16
export const STEPS_PER_SONG = STEPS_PER_BAR * BARS_PER_SONG
export const MAJOR = [0, 2, 4, 5, 7, 9, 11] as const

/** Common pop/game progressions, as scale degrees, four bars each. */
const PROGRESSIONS: readonly (readonly number[])[] = [
  [0, 5, 3, 4],
  [0, 3, 5, 4],
  [5, 3, 0, 4],
  [0, 2, 3, 4],
  [0, 4, 5, 3],
  [3, 4, 2, 5],
]

/** Rhythm templates for one bar: onset step → length in steps. */
const RHYTHMS: readonly (readonly (readonly [number, number])[])[] = [
  [[0, 3], [3, 1], [4, 2], [6, 2], [8, 4], [12, 2], [14, 2]],
  [[0, 2], [2, 2], [4, 4], [8, 2], [10, 2], [12, 4]],
  [[0, 4], [4, 2], [6, 2], [8, 6], [14, 2]],
  [[0, 1], [2, 1], [4, 2], [6, 2], [8, 3], [11, 1], [12, 4]],
  [[0, 6], [6, 2], [8, 2], [10, 2], [12, 2], [14, 2]],
]

export function mulberry32(seed: number): () => number {
  let a = seed >>> 0
  return () => {
    a = (a + 0x6d2b79f5) >>> 0
    let t = a
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

/** MIDI note for a scale index (may be negative or above 7) in a key. */
export function scaleNote(root: number, index: number): number {
  const oct = Math.floor(index / 7)
  const deg = ((index % 7) + 7) % 7
  return root + oct * 12 + MAJOR[deg]!
}

/** Scale indices of the triad on a degree. */
export function triad(degree: number): [number, number, number] {
  return [degree, degree + 2, degree + 4]
}

export function midiToHz(midi: number): number {
  return 440 * 2 ** ((midi - 69) / 12)
}

/** Nearest scale index to `from` (in scale steps) that is a chord tone. */
function nearestChordTone(from: number, degree: number): number {
  const tones = triad(degree).map((d) => ((d % 7) + 7) % 7)
  for (let dist = 0; dist < 7; dist++) {
    for (const cand of [from - dist, from + dist]) if (tones.includes(((cand % 7) + 7) % 7)) return cand
  }
  return from
}

/** One bar of melody, as [onset, length, scale index] triples. */
function makeBar(random: () => number, degree: number, start: number, rhythm: readonly (readonly [number, number])[]): [number, number, number][] {
  const out: [number, number, number][] = []
  let idx = nearestChordTone(start, degree)
  for (const [onset, len] of rhythm) {
    const strong = onset % 8 === 0
    if (strong) idx = nearestChordTone(idx + Math.round((random() - 0.5) * 3), degree)
    else {
      const r = random()
      idx += r < 0.4 ? 1 : r < 0.8 ? -1 : r < 0.9 ? 2 : -2
    }
    // Keep the tune within about an octave and a half around the tonic.
    if (idx > 9) idx -= 2
    if (idx < -2) idx += 2
    if (len >= 4) idx = nearestChordTone(idx, degree)
    out.push([onset, len, idx])
  }
  return out
}

export function makeSong(seed: number): Song {
  const random = mulberry32(seed * 7919 + 17)
  const root = 60 + [0, 2, 3, 5, 7, -1, -3][Math.floor(random() * 7)]!
  const progA = PROGRESSIONS[Math.floor(random() * PROGRESSIONS.length)]!
  const progB = PROGRESSIONS[Math.floor(random() * PROGRESSIONS.length)]!
  // Form: A A' B A, four bars each.
  const chords = [...progA, ...progA, ...progB, ...progA]
  const rhythmA = RHYTHMS[Math.floor(random() * RHYTHMS.length)]!
  const rhythmB = RHYTHMS[Math.floor(random() * RHYTHMS.length)]!
  const motifA = progA.map((d, i) => makeBar(random, d, i === 0 ? 4 : 2, i % 2 ? rhythmB : rhythmA))
  const motifA2 = progA.map((d, i) => (i < 2 ? motifA[i]! : makeBar(random, d, 4, rhythmA)))
  const motifB = progB.map((d) => makeBar(random, d, 5, rhythmB))
  const melody = [...motifA, ...motifA2, ...motifB, ...motifA]
  const bassStyle = Math.floor(random() * 3)
  const arpUp = random() < 0.5

  const steps: StepEvents[] = Array.from({ length: STEPS_PER_SONG }, () => ({}))
  chords.forEach((degree, bar) => {
    const base = bar * STEPS_PER_BAR
    const last = bar === BARS_PER_SONG - 1
    // Lead.
    // The song ends on one held tonic: the first melody note from the middle of the last bar on.
    let held = false
    for (const [onset, len, idx] of melody[bar]!) {
      const finalNote = last && onset >= 8
      if (finalNote && held) continue
      held ||= finalNote
      steps[base + onset]!.lead = { midi: scaleNote(root, finalNote ? 7 : idx), steps: finalNote ? STEPS_PER_BAR - onset : len }
    }
    // Arpeggio: chord tones cycling every sixteenth, one octave up, quiet.
    const tones = triad(degree).map((d) => scaleNote(root, d + 7))
    const order = arpUp ? [0, 1, 2, 1] : [2, 1, 0, 1]
    for (let s = 0; s < STEPS_PER_BAR; s++) steps[base + s]!.arp = { midi: tones[order[s % 4]!]!, steps: 1 }
    // Bass: two octaves below, root on the downbeat.
    const rootBass = scaleNote(root, degree) - 24
    const fifthBass = scaleNote(root, degree + 4) - 24
    const pattern: [number, number, number][] =
      bassStyle === 0
        ? [[0, rootBass, 4], [4, rootBass + 12, 4], [8, rootBass, 4], [12, fifthBass, 4]]
        : bassStyle === 1
          ? [[0, rootBass, 6], [6, rootBass, 2], [8, fifthBass, 6], [14, rootBass + 12, 2]]
          : [[0, rootBass, 2], [2, rootBass, 2], [4, fifthBass, 2], [6, rootBass, 2], [8, rootBass + 12, 2], [10, rootBass, 2], [12, fifthBass, 2], [14, rootBass, 2]]
    for (const [onset, midi, len] of pattern) steps[base + onset]!.bass = { midi, steps: len }
    // Drums: kick on 1 and 3, snare on 2 and 4, hats on the off-beats; a fill every fourth bar.
    for (let s = 0; s < STEPS_PER_BAR; s++) {
      const fill = bar % 4 === 3
      let drum: Drum | undefined
      if (s === 0 || s === 8) drum = 'kick'
      else if (s === 4 || s === 12 || (fill && (s === 14 || s === 15))) drum = 'snare'
      else if (s % 2 === 0) drum = 'hat'
      if (drum) steps[base + s]!.drum = drum
    }
  })
  return { seed, root, chords, steps }
}

const cache = new Map<number, Song>()

/** Events for an absolute step: songs follow each other, each from the next seed. */
export function eventsAt(baseSeed: number, step: number): StepEvents {
  const songIndex = Math.floor(step / STEPS_PER_SONG)
  const seed = baseSeed + songIndex
  let song = cache.get(seed)
  if (!song) {
    song = makeSong(seed)
    cache.set(seed, song)
    if (cache.size > 4) cache.delete(cache.keys().next().value!)
  }
  return song.steps[((step % STEPS_PER_SONG) + STEPS_PER_SONG) % STEPS_PER_SONG]!
}

/** First step of the next bar (or this one, if already on a bar line): where songs can switch without a jolt. */
export function nextBarStep(step: number): number {
  return Math.ceil(step / STEPS_PER_BAR) * STEPS_PER_BAR
}

/** The calm planning-screen arrangement: melody and bass, a soft kick, no arpeggio, snare or hi-hat. */
export function calmEvents(ev: StepEvents): StepEvents {
  const out: StepEvents = {}
  if (ev.lead) out.lead = ev.lead
  if (ev.bass) out.bass = ev.bass
  if (ev.drum === 'kick') out.drum = 'kick'
  return out
}
